class Agenthub < Formula
  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/agent-hub"
  version "0.40.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.40.0/agenthub-0.40.0-5f13770-darwin-arm64.tar.gz"
      sha256 "f0a853c496a4619db0fdc0ddd500c96581ca6c5c2bfd259cdb83a8ce9d50fd59"
    end
    on_intel do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.40.0/agenthub-0.40.0-5f13770-darwin-amd64.tar.gz"
      sha256 "ea7e0c7c8a6ffdb8e0a2e4f554737020691a9d2ad11631d9a9c17b4546e08a92"
