  on_linux do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.40.0/agenthub-0.40.0-5f13770-linux-arm64.tar.gz"
      sha256 "ac06c63fcd8808c2a42fe193b3e1852b216e5aa9c7bde75671b6baea85c2e2e0"
